// Restores data/*.json to a clean demo state:
//   - students.json, fees.json, resources.json <- copied from data/seed/
//   - users.json <- regenerated by scripts/seed.js (fresh password hashes)
//   - leads.json, notifications.json, alert-state.json <- emptied
//
// Run this before a demo, before committing, or anytime test data (leads
// submitted via curl, scores you were just testing, etc.) needs clearing
// without hand-editing JSON files.
//
// Run: node scripts/reset-demo-data.js

const fs = require("node:fs");
const path = require("node:path");
const { execSync } = require("node:child_process");

const dataDir = path.join(__dirname, "..", "data");
const seedDir = path.join(dataDir, "seed");

for (const file of ["students.json", "fees.json", "resources.json"]) {
  fs.copyFileSync(path.join(seedDir, file), path.join(dataDir, file));
  console.log(`Restored ${file}`);
}

execSync(`node "${path.join(__dirname, "seed.js")}"`, { stdio: "inherit" });

for (const file of ["leads.json", "notifications.json", "alert-state.json"]) {
  fs.writeFileSync(path.join(dataDir, file), "[]");
  console.log(`Cleared ${file}`);
}

console.log("\nDemo data reset to a clean state.");
